63	/// Validates that all source path keys are relative and contain no traversal components.
64	/// Absolute paths (`/foo`) and parent-directory references (`../foo`) allow the compiler
65	/// to read arbitrary files from the container filesystem, so both are rejected here.
66	pub(crate) fn validate_source_paths(
67	    sources: &HashMap<String, Source>,
68	) -> Result<(), ContractVerifierError> {
69	    for path in sources.keys() {
70	        if path.starts_with('/')
71	            || path.starts_with("file://")
72	            || path.split('/').any(|component| component == "..")
73	        {
74	            return Err(ContractVerifierError::InvalidSourcePath(path.clone()));
75	        }
76	    }
77	    Ok(())
78	}
