80	/// Returns `true` if `source` contains an `import` directive whose path is absolute (`/…`)
81	/// or uses a `file://` URL. These forms let the compiler resolve imports against the host
82	/// filesystem and potentially leak file contents in error messages.
83	///
84	/// Relative imports containing `../` are allowed: they are standard Solidity practice and
85	/// remain sandboxed by `validate_source_paths()` plus the empty compiler search directory.
86	pub(crate) fn has_dangerous_imports(source: &str) -> bool {
87	    // Covers all Solidity import forms:
88	    //   import "/path";
89	    //   import {X} from "/path";
90	    //   import * as X from "/path";
91	    //   import "file:///path";
