96	/// Strips pipe-prefixed source-snippet lines from a compiler `formattedMessage`.
97	///
98	/// The `formattedMessage` format looks like:
99	/// ```text
100	/// ParserError: Expected ';' but got end of source
101	///  --> /etc/shadow:1:5:
102	///   |
103	/// 1 | root:*:19970:0:99999:7:::
104	///   |     ^
105	/// ```
106	/// Lines starting with optional whitespace followed by `|` contain verbatim file
107	/// contents and must be removed.  The ` --> path:line:col` header is kept because
108	/// it only reveals the path (which the caller already submitted) and the position.
109	fn strip_source_snippets(msg: &str) -> String {
110	    msg.lines()
111	        .filter(|line| !line.trim_start().starts_with('|'))
112	        .collect::<Vec<_>>()
113	        .join("\n")
114	}
